@dataclass
class Job:
    index: int
    total: int
    seed: int
    policy: str


_PRINT_LOCK = Lock()


def log(message: str) -> None:
    with _PRINT_LOCK:
        print(message, flush=True)


def connect_readonly(path: str) -> sqlite3.Connection:
    # URI read-only connection. WAL is not enabled or modified.
    uri = "file:" + os.path.abspath(path).replace("\\", "/") + "?mode=ro"
    con = sqlite3.connect(
        uri,
        uri=True,
        check_same_thread=False,
        timeout=30.0,
    )
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA query_only=ON")
    con.execute("PRAGMA busy_timeout=30000")
    return con


def discover_edge_columns(con):
    """Resolve subject/relation/object columns from the actual edges schema."""
    cols = [
        row[1] for row in con.execute("PRAGMA table_info(edges)").fetchall()
    ]
    if not cols:
        raise RuntimeError("Table 'edges' does not exist or has no columns")

    lower = {c.lower(): c for c in cols}

    def pick(names):
        for n in names:
            if n in lower:
                return lower[n]
        return None

    subject = pick([
        "subject", "subj", "source", "src", "s",
        "subject_id", "source_id",
    ])
    relation = pick([
        "predicate", "relation", "rel", "property", "r",
        "predicate_id", "relation_id",
    ])
    obj = pick([
        "object", "obj", "target", "dst", "o",
        "object_id", "target_id",
    ])

    # If conventional names aren't present, use the first three columns only
    # when they are unambiguous. This is preferable to silently guessing.
    if not (subject and relation and obj):
        raise RuntimeError(
            "Could not resolve edges S/R/O columns. "
            f"Actual columns: {cols}"
        )

    return subject, relation, obj


def discover_oracle(args, con):
    """
    Self-contained oracle construction using the real edges schema.

    previous-version never assumes columns are literally named s/r/o. The resolved mapping
    is printed and then reused for all graph access.
    """
    subject, relation, obj = discover_edge_columns(con)

    print("")
    print("=== EDGE SCHEMA ===", flush=True)
    print(f"subject            : {subject}", flush=True)
    print(f"relation           : {relation}", flush=True)
    print(f"object             : {obj}", flush=True)

    q_ident = lambda x: '"' + x.replace('"', '""') + '"'
    S, R, O = map(q_ident, (subject, relation, obj))

    preferred = [
        "schema:location",
        "schema:birthPlace",
        "schema:nationality",
        "schema:knowsLanguage",
        "birthPlace",
        "is_a",
        "yago:hasMother",
        "team",
        "schema:inLanguage",
    ]

    existing = {
        row[0] for row in con.execute(
            f"SELECT DISTINCT {R} FROM edges WHERE {R} IS NOT NULL"
        )
    }

    counts = dict(
        con.execute(
            f"SELECT {R}, COUNT(*) FROM edges "
            f"WHERE {R} IS NOT NULL GROUP BY {R}"
        ).fetchall()
    )

    targets = [r for r in preferred if r in existing]

    ranked = sorted(
        ((r, n) for r, n in counts.items() if r not in targets),
        key=lambda x: (-x[1], str(x[0])),
    )
    target_n = max(1, min(args.top_predicates, len(counts)))
    for r, _ in ranked:
        if len(targets) >= target_n:
            break
        targets.append(r)

    targets = targets[:target_n]

    print("")
    print("=== ORACLE ===", flush=True)
    print(f"target relations : {len(targets)}", flush=True)

    cases = []
    supported = 0
    negatives = 0
    per_rel = max(
        1,
        min(
            args.supported_per_relation,
            args.negative_per_relation,
        ),
    )

    for rel in targets:
        rows = con.execute(
            f"SELECT {S}, {O} FROM edges "
            f"WHERE {R}=? AND {S} IS NOT NULL AND {O} IS NOT NULL "
            f"LIMIT ?",
            (rel, max(args.sample_each, per_rel * 4)),
        ).fetchall()

        if not rows:
            continue

        positives = rows[:per_rel]
        for s, o in positives:
            cases.append({
                "subject": s,
                "relation": rel,
                "object": o,
                "label": 1,
                "positive": True,
            })
            supported += 1

        # Prefer same-subject alternatives as hard negatives.
        for s, true_o in positives:
            neg_rows = con.execute(
                f"SELECT {O} FROM edges "
                f"WHERE {S}=? AND {R}=? AND {O}<>? "
                f"AND {O} IS NOT NULL LIMIT ?",
                (s, rel, true_o, max(4, args.negative_per_relation)),
            ).fetchall()

            if not neg_rows:
                neg_rows = con.execute(
                    f"SELECT {O} FROM edges "
                    f"WHERE {S}=? AND {R}<>? AND {O} IS NOT NULL LIMIT ?",
                    (s, rel, max(4, args.negative_per_relation)),
                ).fetchall()

            if not neg_rows:
                continue

            no = neg_rows[0][0]
            cases.append({
                "subject": s,
                "relation": rel,
                "object": no,
                "label": 0,
                "positive": False,
                "hard_negative": True,
            })
            negatives += 1

    if args.case_cap:
        cap = args.case_cap * max(1, len(targets))
        cases = cases[:cap]

    print(f"supported        : {supported}", flush=True)
    print(f"hard negatives   : {negatives}", flush=True)
    print(f"total             : {len(cases)}", flush=True)
    for r in targets:
        print(f"  {r}", flush=True)

    return cases, {}


_EMBEDDED_RELATION_PROFILES_B64 = ""


def load_profiles(_args=None):
    """Return the embedded relation-transition profiles; no external artifact."""
    raw = base64.b64decode(_EMBEDDED_RELATION_PROFILES_B64).decode("utf-8")
    return json.loads(raw)


def make_job_cases(cases, seed):
    # Keep case order identical across jobs. Seed only controls the controller.
    return list(cases)






class PathScoreStats:
    def __init__(self):
        self.cases = 0
        self.expansions = 0
        self.generated = 0
        self.pruned = 0
        self.forward_queries = 0
        self.reverse_queries = 0
        self.cache_hits = 0
        self.cache_misses = 0
        self.two_hop_candidates = 0
        self.three_hop_candidates = 0
        self.verified_proofs = 0
        self.false_proofs = 0
        self.direct_rejections = 0
        self.depth1_states = 0
        self.depth2_states = 0
        self.depth3_states = 0
        self.max_frontier = 0
        self.path_patterns = defaultdict(int)
        self.success_patterns = defaultdict(int)
        self.failure_patterns = defaultdict(int)


class _Case:
    __slots__ = (
        "subject",
        "target_relation",
        "object",
        "source_predicate",
        "kind",
        "gold",
        "path",
    )

    def __init__(
        self,
        subject,
        target_relation,
        object,
        source_predicate,
        kind,
        gold,
        path,
    ):
        self.subject = subject
        self.target_relation = target_relation
        self.object = object
        self.source_predicate = source_predicate
        self.kind = kind
        self.gold = gold
        self.path = path


def normalize_cases(cases):
    out = []

    for raw in cases:
        if not isinstance(raw, dict):
            out.append(raw)
            continue

        relation = raw.get(
            "target_relation",
            raw.get("relation"),
        )

        subject = raw.get("subject")
        object_ = raw.get("object")

        if (
            subject is None
            or relation is None
            or object_ is None
        ):
            raise RuntimeError(
                "Malformed case: "
                f"expected subject/relation/object; "
                f"keys={sorted(raw)}"
            )

        gold = bool(
            raw.get(
                "gold",
                raw.get(
                    "label",
                    raw.get(
                        "positive",
                        False,
                    ),
                ),
            )
        )

        out.append(
            _Case(
                subject=str(subject),
                target_relation=str(relation),
                object=str(object_),
                source_predicate=str(
                    raw.get(
                        "source_predicate",
                        relation,
                    )
                ),
                kind=str(
                    raw.get(
                        "kind",
                        "SUPPORTED"
                        if gold
                        else "HARD_NEGATIVE",
                    )
                ),
                gold=gold,
                path=tuple(
                    tuple(edge)
                    for edge in raw.get(
                        "path",
                        (),
                    )
                ),
            )
        )

    return out


def forward_edges(
    con,
    node,
    limit,
    hidden,
    cache,
    stats,
):
    key = node

    if key in cache:
        stats.cache_hits += 1
        rows = cache[key]
    else:
        stats.cache_misses += 1
        stats.forward_queries += 1

        rows = tuple(
            (
                str(row["relation"]),
                str(row["object"]),
                row["source"],
            )
            for row in con.execute(
                """
                SELECT relation, object, source
                FROM edges
                WHERE subject=?
                LIMIT ?
                """,
                (
                    node,
                    limit,
                ),
            )
        )

        cache[key] = rows

    hidden_pairs = {
        (r, o)
        for s, r, o in hidden
        if s == node
    }

    return [
        row
        for row in rows
        if (
            row[0],
            row[1],
        ) not in hidden_pairs
    ]


def incoming_target_edges(
    con,
    target_object,
    relation,
    limit,
    hidden,
    cache,
    stats,
):
    key = (
        target_object,
        relation,
        limit,
    )

    if key in cache:
        stats.cache_hits += 1
        rows = cache[key]
    else:
        stats.cache_misses += 1
        stats.reverse_queries += 1

        rows = tuple(
            (
                str(row["subject"]),
                str(row["relation"]),
                str(row["object"]),
                row["source"],
            )
            for row in con.execute(
                """
                SELECT subject, relation, object, source
                FROM edges
                WHERE object=?
                  AND relation=?
                LIMIT ?
                """,
                (
                    target_object,
                    relation,
                    limit,
                ),
            )
        )

        cache[key] = rows

    hidden_set = set(hidden)

    return [
        row
        for row in rows
        if (
            row[0],
            row[1],
            row[2],
        ) not in hidden_set
    ]


def transition_value(
    profiles,
    relation_a,
    relation_b,
):
    if relation_a is None:
        return 0.0

    profile = profiles.get(
        relation_a
    )

    if not profile:
        return 0.0

    try:
        return float(
            v575.second_profile(
                profile
            ).get(
                relation_b,
                0.0,
            )
        )
    except Exception:
        return 0.0


def path_score(
    profiles,
    relations,
    target_relation,
    success_prior=None,
    prior_decay=0.65,
):
    """
    Whole-path score.

    The score intentionally treats a relation sequence as a unit:
        r1 -> r2 -> target
    rather than independently rewarding r1/r2.
    """
    if not relations:
        return -1e9

    score = 0.0

    # Pairwise composition.
    for left, right in zip(
        relations,
        relations[1:],
    ):
        score += 2.5 * transition_value(
            profiles,
            left,
            right,
        )

    # Explicit closure into the target.
    score += 4.0 * transition_value(
        profiles,
        relations[-1],
        target_relation,
    )

    # Small length regularizer: prefer shorter proofs when scores tie.
    score -= 0.20 * len(relations)

    # previous-version: exploit verified path patterns discovered by previous-version.
    # This is a soft ranking prior, never a hard gate.  Prefixes receive
    # partial credit so the controller can learn toward known-good routes
    # before the full target relation is reached.
    if success_prior:
        # Annealed prior: strongest at the first hop, weaker as the path
        # gets deeper. This tests whether the controller should exploit
        # learned routes without becoming over-committed to them.
        decay = max(0.0, min(1.0, prior_decay))
        for n in range(1, len(relations) + 1):
            pattern = " -> ".join(relations[:n])
            count = success_prior.get(pattern, 0.0)
            if count:
                weight = decay ** (n - 1)
                score += 1.25 * weight * math.log1p(count) / n

    return score


def verify_path(
    con,
    path,
    target_relation,
    target_object,
):
    if len(path) < 2:
        return False

    if (
        path[-1][1] != target_relation
        or path[-1][2] != target_object
    ):
        return False

    for left, right in zip(
        path,
        path[1:],
    ):
        if left[2] != right[0]:
            return False

    for subject, relation, object_ in path:
        row = con.execute(
            """
            SELECT 1
            FROM edges
            WHERE subject=?
              AND relation=?
              AND object=?
            LIMIT 1
            """,
            (
                subject,
                relation,
                object_,
            ),
        ).fetchone()

        if row is None:
            return False

    return True


def goal_directed_path_policy(
    con,
    cases,
    budget,
    per_node,
    max_depth,
    profiles,
    neighbors,
    seed,
    max_case_seconds,
    progress_every,
    success_prior=None,
    max_probes_per_case=500,
    prior_decay=0.65,
):
    """
    V599 — Annealed best-first goal-directed path search.

    previous-version demonstrated that verified path priors improve proof recovery.
    V599 moved the prior into best-first search ordering.
    V599 changes one thing only: prior influence is annealed by depth, so
    early hops exploit known-good prefixes while deeper hops regain
    composition/target evidence and exploration.

    Unlike previous-version's layer-wise beam:
        score -> keep top beam -> expand every retained state

    V599 maintains one priority frontier per case:
        highest-scoring partial path -> expand -> push children

    Thus a strong path prefix can reach depth 2/3 before weak prefixes are
    expanded.  The path prior remains a soft preference, never a hard gate.
    Every returned proof is still verified against SQLite.
    """
    cases = normalize_cases(cases)

    started = time.perf_counter()
    total = len(cases)

    supported = sum(1 for case in cases if case.gold)
    negatives = total - supported

    correct = 0
    supported_correct = 0
    false_positive = 0
    predicted_positive = 0
    total_steps = 0
    path_lengths = []

    stats = PathScoreStats()
    forward_cache = {}

    edge_width = max(16, min(per_node, 40))

    # V599 diagnostics: these make the search-order effect measurable.
    frontier_pops = 0
    frontier_pushes = 0
    budget_exhausted = 0
    case_timeouts = 0

    for index, case in enumerate(cases, 1):
        case_started = time.perf_counter()

        hidden = {
            (case.subject, case.target_relation, case.object)
        } if case.gold else set()

        # Heap entries:
        #   (-score, depth, tie_break, node, path, relations, visited)
        #
        # A monotonic tie-break keeps ordering deterministic without relying
        # on Python object comparison.
        frontier = []
        tie = 0
        expansions_this_case = 0
        found_path = None

        first = forward_edges(
            con,
            case.subject,
            edge_width,
            hidden,
            forward_cache,
            stats,
        )

        for relation, object_, source in first:
            stats.expansions += 1
            expansions_this_case += 1

            if relation == case.target_relation and object_ == case.object:
                stats.direct_rejections += 1
                continue

            path = ((case.subject, relation, object_),)
            relations = (relation,)
            visited = frozenset((case.subject, object_))
            score = path_score(
                profiles,
                relations,
                case.target_relation,
                success_prior,
                prior_decay,
            )

            tie += 1
            heapq.heappush(
                frontier,
                (
                    -score,
                    1,
                    tie,
                    object_,
                    path,
                    relations,
                    visited,
                ),
            )
            frontier_pushes += 1
            stats.generated += 1
            stats.path_patterns[" -> ".join(relations)] += 1

        stats.depth1_states += len(frontier)
        stats.max_frontier = max(stats.max_frontier, len(frontier))

        # Genuine best-first search.  The queue can contain mixed depths;
        # there is no mandatory "expand all depth-2 states before depth 3".
        while frontier and not found_path:
            if (
                max_case_seconds > 0
                and time.perf_counter() - case_started >= max_case_seconds
            ):
                case_timeouts += 1
                stats.cases_aborted = getattr(stats, "cases_aborted", 0) + 1
                break

            if (
                max_probes_per_case > 0
                and expansions_this_case >= max_probes_per_case
            ):
                budget_exhausted += 1
                break

            (
                neg_score,
                depth,
                _tie,
                node,
                path,
                relations,
                visited,
            ) = heapq.heappop(frontier)

            frontier_pops += 1

            if depth >= max_depth:
                continue

            edges = forward_edges(
                con,
                node,
                edge_width,
                hidden,
                forward_cache,
                stats,
            )

            for relation, object_, source in edges:
                stats.expansions += 1
                expansions_this_case += 1

                if object_ in visited:
                    stats.pruned += 1
                    continue

                new_path = path + ((node, relation, object_),)
                new_relations = relations + (relation,)
                new_depth = depth + 1

                score = path_score(
                    profiles,
                    new_relations,
                    case.target_relation,
                    success_prior,
                    prior_decay,
                )

                pattern = " -> ".join(new_relations)
                stats.path_patterns[pattern] += 1
                stats.generated += 1

                if (
                    relation == case.target_relation
                    and object_ == case.object
                ):
                    if new_depth == 2:
                        stats.two_hop_candidates += 1
                    elif new_depth == 3:
                        stats.three_hop_candidates += 1

                    if verify_path(
                        con,
                        new_path,
                        case.target_relation,
                        case.object,
                    ):
                        found_path = new_path
                        stats.verified_proofs += 1
                        stats.success_patterns[pattern] += 1
                        break

                if new_depth < max_depth:
                    tie += 1
                    heapq.heappush(
                        frontier,
                        (
                            -score,
                            new_depth,
                            tie,
                            object_,
                            new_path,
                            new_relations,
                            visited | {object_},
                        ),
                    )
                    frontier_pushes += 1

                    if new_depth == 2:
                        stats.depth2_states += 1
                    elif new_depth == 3:
                        stats.depth3_states += 1

                    stats.max_frontier = max(
                        stats.max_frontier,
                        len(frontier),
                    )

            # Do not expand the remainder of the current state's adjacency
            # list once a verified proof has been found.
            if found_path:
                break

        pred = found_path is not None

        if pred:
            predicted_positive += 1
            path_lengths.append(len(found_path))

        if pred:
            if case.gold:
                correct += 1
                supported_correct += 1
            else:
                false_positive += 1
                stats.false_proofs += 1
        elif not case.gold:
            correct += 1

        total_steps += min(
            budget,
            expansions_this_case,
        )

        if (
            progress_every > 0
            and (
                index == 1
                or index % progress_every == 0
                or index == total
            )
        ):
            elapsed = time.perf_counter() - started
            rate = index / max(elapsed, 1e-9)
            eta = (total - index) / max(rate, 1e-9)

            print(
                f"    [CASE {index}/{total}] prior_search "
                f"rate={rate:.2f}/s "
                f"elapsed={elapsed:.1f}s "
                f"eta={eta:.1f}s "
                f"frontier={len(frontier):,} "
                f"pops={frontier_pops:,} "
                f"verified={stats.verified_proofs:,} "
                f"2hop={stats.two_hop_candidates:,} "
                f"3hop={stats.three_hop_candidates:,} "
                f"cache={len(forward_cache):,}",
                flush=True,
            )

    stats.frontier_pops = frontier_pops
    stats.frontier_pushes = frontier_pushes
    stats.case_timeouts = case_timeouts

    return {
        "accuracy": correct / max(1, total),
        "supported_cases": supported,
        "supported_recovery": supported_correct / max(1, supported),
        "negative_cases": negatives,
        "false_proof_rate": false_positive / max(1, negatives),
        "predicted_positive": predicted_positive,
        "mean_steps": total_steps / max(1, total),
        "mean_path_length": (
            sum(path_lengths) / max(1, len(path_lengths))
        ),
        "budget_exhausted": budget_exhausted,
        "controller_stats": {
            "cases": stats.cases,
            "expansions": stats.expansions,
            "generated": stats.generated,
            "pruned": stats.pruned,
            "forward_queries": stats.forward_queries,
            "reverse_queries": stats.reverse_queries,
            "cache_hits": stats.cache_hits,
            "cache_misses": stats.cache_misses,
            "two_hop_candidates": stats.two_hop_candidates,
            "three_hop_candidates": stats.three_hop_candidates,
            "verified_proofs": stats.verified_proofs,
            "false_proofs": stats.false_proofs,
            "direct_rejections": stats.direct_rejections,
            "depth1_states": stats.depth1_states,
            "depth2_states": stats.depth2_states,
            "depth3_states": stats.depth3_states,
            "max_frontier": stats.max_frontier,
            "frontier_pops": frontier_pops,
            "frontier_pushes": frontier_pushes,
            "case_timeouts": case_timeouts,
            "top_success_patterns": sorted(
                stats.success_patterns.items(),
                key=lambda x: (-x[1], x[0]),
            )[:25],
            "top_path_patterns": sorted(
                stats.path_patterns.items(),
                key=lambda x: (-x[1], x[0]),
            )[:25],
        },
        "policy_seconds": time.perf_counter() - started,
    }

def run_one(job: Job, args, cases, profiles, neighbors, success_prior):
    started = time.perf_counter()
    con = connect_readonly(args.database)

    try:
        log(
            f"[JOB {job.index:03d}/{job.total:03d}] START "
            f"seed={job.seed} policy={job.policy}"
        )

        result = goal_directed_path_policy(
            con=con,
            cases=cases,
            budget=args.budget,
            per_node=args.per_node,
            max_depth=max(2, args.max_depth),
            profiles=profiles,
            neighbors=neighbors,
            seed=job.seed,
            max_case_seconds=args.max_case_seconds,
            progress_every=args.progress_every,
            success_prior=success_prior,
            max_probes_per_case=args.max_probes_per_case,
        )

        elapsed = time.perf_counter() - started

        log(
            f"[JOB {job.index:03d}/{job.total:03d}] END "
            f"seed={job.seed} policy={job.policy} "
            f"acc={result['accuracy']:.4f} "
            f"recover={result['supported_recovery']:.4f} "
            f"false={result['false_proof_rate']:.4f} "
            f"steps={result['mean_steps']:.2f} "
            f"verified={result['controller_stats']['verified_proofs']:,} "
            f"elapsed={elapsed:.1f}s"
        )

        return {
            "job": asdict(job),
            "elapsed_seconds": elapsed,
            "result": result,
        }
    finally:
        con.close()


def normalize_result(row):
    """
    Make heterogeneous V575 evaluator return shapes JSON-safe.
    """
    result = row.get("result")
    if isinstance(result, dict):
        out = dict(result)
    elif hasattr(result, "__dict__"):
        out = dict(result.__dict__)
    elif isinstance(result, tuple):
        out = {"tuple": list(result)}
    else:
        out = {"value": result}

    row = dict(row)
    row["result"] = out
    return row


def main():
    # V599 preflight: verify the embedded controller API and immutable Case
    # schema before touching the 44+ GB graph.
    import inspect as _inspect
    _preflight_eval = getattr(v575, "evaluate_policy", None)
    _preflight_case = getattr(v575, "Case", None) or getattr(v575, "QueryCase", None)
    if _preflight_eval is None:
        raise RuntimeError(
            "Embedded controller does not expose evaluate_policy()."
        )
    if _preflight_case is None:
        raise RuntimeError(
            "Embedded controller exposes neither Case nor QueryCase."
        )
    log(
        f"[CONTROLLER API] evaluate_policy{_inspect.signature(_preflight_eval)}"
    )
    log(
        f"[CASE SCHEMA] {_preflight_case.__name__}{_inspect.signature(_preflight_case)}"
    )

    ap = argparse.ArgumentParser(
        description="V599 self-contained annealed-prior cognitive benchmark matrix"
    )

    ap.add_argument("--database", required=True)
    ap.add_argument("--output", required=True)

    ap.add_argument("--workers", type=int, default=20)
    ap.add_argument("--seeds", type=int, default=5)
    ap.add_argument("--seed-start", type=int, default=57600)

    ap.add_argument("--budget", type=int, default=80)
    ap.add_argument("--per-node", type=int, default=60)
    ap.add_argument("--max-depth", type=int, default=3)

    ap.add_argument("--cache-entries", type=int, default=12000)
    ap.add_argument("--progress-every", type=int, default=10)
    ap.add_argument("--max-probes-per-case", type=int, default=500)
    ap.add_argument("--max-case-seconds", type=float, default=2.0)
    ap.add_argument("--prior-decay", type=float, default=0.65,
                    help="Verified-path prior decay per additional hop (0..1)")

    ap.add_argument("--top-predicates", type=int, default=20)
    ap.add_argument("--sample-each", type=int, default=600)
    ap.add_argument("--middle-limit", type=int, default=150)
    ap.add_argument("--case-cap", type=int, default=100)
    ap.add_argument("--supported-per-relation", type=int, default=20)
    ap.add_argument("--negative-per-relation", type=int, default=20)

    ap.add_argument("--only-policy", default="")
    ap.add_argument("--skip-bfs", action="store_true")
    ap.add_argument("--skip-depth-branch", action="store_true")

    args = ap.parse_args()

    db = Path(args.database)
    if not db.exists():
        raise FileNotFoundError(db)

    log("=== V599 PARALLEL COGNITIVE MATRIX ===")
    log(f"database             : {db.resolve()}")
    log(f"database size        : {db.stat().st_size / (1024**3):.2f} GB")
    log("embedded relation profiles : YES (compiled into executable)")
    log(f"workers              : {args.workers}")
    log(f"seeds                : {args.seeds}")
    log(f"global jobs          : policies × seeds")
    log(f"cache/job            : {args.cache_entries:,}")
    log("source graph         : READ-ONLY")
    log("mode                 : parallel policy/seed jobs")
    log("nested parallelism   : OFF")

    if args.workers < 1 or args.workers > 20:
        raise ValueError("--workers must be between 1 and 20")

    # The verified path prior is compiled into this file.  There is no
    # runtime dependency on any previous experiment result.
    success_prior = defaultdict(float, json.loads(
        base64.b64decode("").decode("utf-8")
    ))
    log(f"embedded verified-path prior patterns: {len(success_prior):,}")

    con = connect_readonly(str(db))
    try:
        profiles = load_profiles(args)
        oracle = discover_oracle(args, con)
    finally:
        con.close()

    # Normalize common oracle return shapes.
    if isinstance(oracle, tuple):
        cases = oracle[0]
        neighbors = oracle[1] if len(oracle) > 1 else {}
    elif isinstance(oracle, dict):
        cases = oracle.get("cases", oracle.get("oracle", []))
        neighbors = oracle.get("neighbors", {})
    else:
        cases = oracle
        neighbors = {}

    cases = list(cases)

    all_policies = ["goal_directed_prior_search"]

    policies = ["goal_directed_prior_search"]

    jobs = []
    total = len(policies) * args.seeds

    for seed_offset in range(args.seeds):
        seed = args.seed_start + seed_offset
        for policy in policies:
            jobs.append(
                Job(
                    index=len(jobs) + 1,
                    total=total,
                    seed=seed,
                    policy=policy,
                )
            )

    log("")
    log("=== MATRIX ===")
    log(f"policies             : {len(policies)}")
    log(f"seeds                : {args.seeds}")
    log(f"jobs                 : {total}")
    log(f"cases/job            : {len(cases)}")
    log(f"parallel workers     : {args.workers}")
    log("")

    started = time.perf_counter()
    results = []
    failures = []

    # No nested executors: exactly args.workers graph-reading jobs maximum.
    with ThreadPoolExecutor(
        max_workers=args.workers,
        thread_name_prefix="v599",
    ) as pool:
        future_map = {
            pool.submit(
                run_one,
                job,
                args,
                cases,
                profiles,
                neighbors,
                success_prior,
            ): job
            for job in jobs
        }

        completed = 0

        for future in as_completed(future_map):
            job = future_map[future]
            completed += 1

            try:
                row = normalize_result(
                    future.result()
                )
                results.append(row)

                elapsed = time.perf_counter() - started
                rate = completed / max(
                    elapsed,
                    1e-9,
                )
                remaining = total - completed
                eta = remaining / max(
                    rate,
                    1e-9,
                )

                log(
                    f"[MATRIX {completed:03d}/{total:03d}] "
                    f"finished={job.policy}@{job.seed} "
                    f"rate={rate:.2f} jobs/s "
                    f"elapsed={elapsed:.1f}s "
                    f"eta={eta:.1f}s"
                )

            except Exception as exc:
                elapsed = time.perf_counter() - started

                failures.append({
                    "job": asdict(job),
                    "error": f"{type(exc).__name__}: {exc}",
                    "traceback": traceback.format_exc(),
                })

                log(
                    f"[MATRIX {completed:03d}/{total:03d}] "
                    f"ERROR={job.policy}@{job.seed} "
                    f"{type(exc).__name__}: {exc} "
                    f"elapsed={elapsed:.1f}s"
                )

    elapsed = time.perf_counter() - started

    payload = {
        "version": "V599",
        "config": vars(args),
        "policies": policies,
        "jobs": total,
        "cases": len(cases),
        "results": sorted(
            results,
            key=lambda r: (
                r["job"]["seed"],
                r["job"]["policy"],
            ),
        ),
        "failures": failures,
        "elapsed_seconds": elapsed,
    }

    Path(args.output).parent.mkdir(
        parents=True,
        exist_ok=True,
    )
    Path(args.output).write_text(
        json.dumps(
            payload,
            indent=2,
            default=str,
        ),
        encoding="utf-8",
    )

    log("")
    log("========================================================================")
    log("V599 COMPLETE")
    log("========================================================================")
    log(f"jobs completed        : {len(results)}/{total}")
    log(f"job failures          : {len(failures)}")
    log(f"elapsed               : {elapsed:.1f}s")
    log(f"JSON                  : {Path(args.output).resolve()}")

    if failures:
        log("WARNING: one or more jobs failed; see JSON failures[]")


if __name__ == "__main__":
    main()
